css:
.tiles {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 12px;
  padding: 24px;
  font-family: system-ui, sans-serif;
}

.tile {
  position: relative;
  height: 140px;
  overflow: hidden;
  border-radius: 10px;
  background-image: repeating-linear-gradient(90deg, #18181b 0 20px, #ffffff 20px 40px);
  isolation: isolate;
}

.tint {
  position: absolute;
  inset: 20px;
  border-radius: 50%;
  background-color: #f97316;
}

.multiply {
  mix-blend-mode: multiply;
}

.screen {
  mix-blend-mode: screen;
}

.difference {
  mix-blend-mode: difference;
}

.label {
  position: absolute;
  bottom: 6px;
  left: 6px;
  padding: 2px 6px;
  border-radius: 4px;
  background-color: #ffffff;
  font-size: 12px;
}
